/// Slot `slot` of `node`, a node of `kind` (checked in safety builds).
fn @"ir.at"(node: Sexp, comptime kind: Tag, comptime slot: usize, comptime what: []const u8) Sexp {
    @"ir.check"(node, kind, what);
    const items = node.items();
    return if (slot < items.len) items[slot] else .nil;
}

/// The children of `node` from `slot` on.
fn @"ir.restAt"(node: Sexp, comptime kind: Tag, comptime slot: usize, comptime what: []const u8) []const Sexp {
    @"ir.check"(node, kind, what);
    const items = node.items();
    return if (slot < items.len) items[slot..] else &.{};
}

fn @"ir.check"(node: Sexp, comptime kind: Tag, comptime what: []const u8) void {
    if (@import("builtin").optimize.runtimeSafety() and !node.isKind(kind)) {
        const actual = if (node.kind()) |k| @tagName(k) else @tagName(node);
        std.debug.panic(what ++ ": node is '{s}', not '" ++ @tagName(kind) ++ "'", .{actual});
    }
}


// =============================================================================
// Grammar
// =============================================================================

/// Node spans and rule ids are recorded (`@schema` or `--spans`).
pub const nodeStore = true;
/// Element extents are kept for side-band labels and nested nodes.
const elemEnds = true;
/// Lists keep trailing nils: positions are fixed by the schema.
const keepTrailingNils = true;
const hasTrivia = false;
/// The grammar has `@repair`: `parseTolerant` is available.
pub const hasRepair = true;
/// `@as` groups the promotable token may become (see `promote`).
const asGroups = 0;
const numSymbols = 365;
const endSymbol: u16 = 1;
const errorSymbol: u16 = 2;

inline fn tokenToSymbol(token: Token) u16 {
    return switch (token.cat) {
        .@"eof" => 1,
        .@"container_doc_comment" => 215,
        .@"doc_comment" => 218,
        .@"string_literal" => 227,
        .@"identifier" => 229,
        .@"label" => 237,
        .@"minus_prefix" => 259,
        .@"minus_percent_prefix" => 262,
        .@"ampersand_prefix" => 264,
        .@"ptr_star" => 276,
        .@"c_ptr" => 278,
        .@"asterisk_prefix" => 280,
        .@"number_literal" => 288,
        .@"char_literal" => 289,
        .@"multiline_string_literal_line" => 290,
        .@"builtin" => 292,
        .@"enum_tag" => 297,
        .@"break_colon" => 306,
        .@"pipe_payload" => 357,
        .@"invalid" => 358,
        .@"bad_doc_comment" => 359,
        .@"bad_operator" => 360,
        .@"comma" => 217,
        .@"semicolon" => 222,
        .@"bang" => 234,
        .@"colon" => 238,
        .@"equal" => 239,
        .@"l_paren" => 245,
        .@"r_paren" => 246,
        .@"l_brace" => 252,
        .@"r_brace" => 254,
        .@"minus" => 258,
        .@"tilde" => 260,
        .@"ampersand" => 263,
        .@"question_mark" => 272,
        .@"l_bracket" => 275,
        .@"r_bracket" => 277,
        .@"asterisk" => 279,
        .@"period" => 286,
        .@"angle_bracket_left" => 337,
        .@"angle_bracket_right" => 338,
        .@"caret" => 341,
        .@"pipe" => 342,
        .@"plus" => 347,
        .@"slash" => 353,
        .@"percent" => 354,
        .@"keyword_test" => 220,
        .@"keyword_comptime" => 221,
        .@"keyword_pub" => 223,
        .@"keyword_threadlocal" => 224,
        .@"keyword_export" => 225,
        .@"keyword_extern" => 226,
        .@"keyword_inline" => 230,
        .@"keyword_noinline" => 231,
        .@"keyword_fn" => 232,
        .@"keyword_const" => 235,
        .@"keyword_var" => 236,
        .@"keyword_nosuspend" => 240,
        .@"keyword_suspend" => 241,
        .@"keyword_defer" => 242,
        .@"keyword_errdefer" => 243,
        .@"keyword_if" => 244,
        .@"keyword_else" => 247,
        .@"keyword_while" => 248,
        .@"keyword_for" => 249,
        .@"keyword_or" => 255,
        .@"keyword_and" => 256,
        .@"keyword_catch" => 257,
        .@"minus_percent" => 261,
        .@"keyword_try" => 265,
        .@"keyword_return" => 266,
        .@"keyword_break" => 267,
        .@"keyword_continue" => 268,
        .@"keyword_resume" => 269,
        .@"keyword_anyframe" => 273,
        .@"arrow" => 274,
        .@"keyword_align" => 281,
        .@"keyword_volatile" => 283,
        .@"keyword_allowzero" => 284,
        .@"ellipsis2" => 285,
        .@"period_asterisk" => 287,
        .@"keyword_error" => 293,
        .@"keyword_unreachable" => 295,
        .@"keyword_union" => 296,
        .@"keyword_packed" => 298,
        .@"keyword_struct" => 299,
        .@"keyword_opaque" => 300,
        .@"keyword_enum" => 301,
        .@"keyword_switch" => 302,
        .@"keyword_asm" => 303,
        .@"keyword_linksection" => 307,
        .@"keyword_addrspace" => 308,
        .@"keyword_callconv" => 309,
        .@"ellipsis3" => 311,
        .@"keyword_noalias" => 312,
        .@"keyword_anytype" => 313,
        .@"equal_angle_bracket_right" => 316,
        .@"asterisk_equal" => 318,
        .@"asterisk_pipe_equal" => 319,
        .@"slash_equal" => 320,
        .@"percent_equal" => 321,
        .@"plus_equal" => 322,
        .@"plus_pipe_equal" => 323,
        .@"minus_equal" => 324,
        .@"minus_pipe_equal" => 325,
        .@"angle_bracket_angle_bracket_left_equal" => 326,
        .@"angle_bracket_angle_bracket_left_pipe_equal" => 327,
        .@"angle_bracket_angle_bracket_right_equal" => 328,
        .@"ampersand_equal" => 329,
        .@"caret_equal" => 330,
        .@"pipe_equal" => 331,
        .@"asterisk_percent_equal" => 332,
        .@"plus_percent_equal" => 333,
        .@"minus_percent_equal" => 334,
        .@"equal_equal" => 335,
        .@"bang_equal" => 336,
        .@"angle_bracket_left_equal" => 339,
        .@"angle_bracket_right_equal" => 340,
        .@"keyword_orelse" => 343,
        .@"angle_bracket_angle_bracket_left" => 344,
        .@"angle_bracket_angle_bracket_right" => 345,
        .@"angle_bracket_angle_bracket_left_pipe" => 346,
        .@"plus_plus" => 348,
        .@"plus_percent" => 349,
        .@"plus_pipe" => 350,
        .@"minus_pipe" => 351,
        .@"pipe_pipe" => 352,
        .@"asterisk_percent" => 355,
        .@"asterisk_pipe" => 356,
        else => 2, // error
    };
}

fn promote(_: *BaseParser, _: Token) u16 {
    unreachable; // no @as group
}

fn executeAction(self: *BaseParser, ruleId: u16, pass: []Sexp) Sexp {
    return switch (ruleId) {
        0 => blk: { const out = self.allocItems(2 + pass[1].items().len) catch break :blk self.oomNil(); var n: usize = 0; out[n] = .{ .tag = .@"root" }; n += 1; out[n] = pass[0]; n += 1; @memcpy(out[n..][0..pass[1].items().len], pass[1].items()); n += pass[1].items().len; break :blk self.finishItems(out, .tree); },
        1 => self.emptyList(.spread),
        2 => blk: { const out = self.extendBy(pass, 0, 1) catch break :blk self.oomNil(); var n = out.len; out.items[n] = pass[1]; n += 1; break :blk self.keepExtended(out, n, pass, 0, .spread, true); },
        3 => blk: { const out = self.allocItems(1 + pass[0].items().len) catch break :blk self.oomNil(); var n: usize = 0; out[n] = .{ .tag = .@"tokens" }; n += 1; @memcpy(out[n..][0..pass[0].items().len], pass[0].items()); n += pass[0].items().len; break :blk self.finishItems(out, .tree); },
        5 => self.buildOf(&.{ .{ .elem = 0 } }, pass, .tree, false),
        6 => blk: { const out = self.extendBy(pass, 0, 1) catch break :blk self.oomNil(); var n = out.len; out.items[n] = pass[1]; n += 1; break :blk self.keepExtended(out, n, pass, 0, .tree, true); },
