/// The `@repair` class of a grammar symbol.
fn repairClass(sym: u16) RepairClass {
    return switch (sym) {
        229 => .hole,
        254 => .structure,
        246 => .structure,
        277 => .structure,
        252 => .structure,
        245 => .structure,
        239 => .structure,
        316 => .structure,
        342 => .structure,
        222 => .terminator,
        else => .none,
    };
}

fn ruleSideLabels(rule: u16) []const SideLabel {
    _ = rule;
    return &.{};
}

